const EXPECTED: &[u8] = b"truncation test file\n";

unsafe fn read_file_contents(dir_fd: wasip1::Fd) -> Vec<u8> {
    let file_fd = wasip1::path_open(dir_fd, 0, FILENAME, 0, wasip1::RIGHTS_FD_READ, 0, 0)
        .expect("opening the file for reading");

    let mut contents = Vec::new();
    let mut buffer = [0u8; 128];
    loop {
        let nread = wasip1::fd_read(
